BEGIN;
  UPDATE accounts SET balance = balance - 1000 WHERE id = 1;
  UPDATE accounts SET balance = balance + 1000 WHERE id = 2;
COMMIT;   -- 둘 다 성공하면 함께 확정
-- 중간에 오류 → ROLLBACK (둘 다 취소, 절반 상태 없음)

-- 애플리케이션: try 안에서 실행, 오류 시 ROLLBACK, 성공 시 COMMIT
-- (대부분 프레임워크: transaction { ... } 블록이 자동 처리)

-- ✗ 위험: 앱에서 읽고 계산해 쓴다 (둘 다 10 읽고 9 씀)
SELECT stock FROM items WHERE id = 1;   -- 앱에서 -1 계산
UPDATE items SET stock = 9 WHERE id = 1;

-- ✓ 원자적 UPDATE: DB 가 현재 값 기준으로 계산
UPDATE items SET stock = stock - 1 WHERE id = 1 AND stock > 0;

-- ✓ 명시적 잠금: 읽을 때 잠가 남이 못 건드리게
SELECT stock FROM items WHERE id = 1 FOR UPDATE;  -- 그다음 계산, 쓰기

-- ✓ 낙관적: 버전 체크 (8장)
UPDATE items SET stock=9, version=version+1 WHERE id=1 AND version=5;
